"""Stage 6: docs/methods/analysis.md rendered from data/analysis/*.json (numbers are never typed by hand)."""
import json
import sys
from pathlib import Path

import pandas as pd

sys.path.insert(0, str(Path(__file__).resolve().parent))
from common import *  # noqa


def P(x, d=1):
    if not x or x.get("pct") is None:
        return "n/a"
    return "%.*f%% [%.*f, %.*f] (%d/%d)" % (d, x["pct"], d, x["ci95"][0], d, x["ci95"][1], x["k"], x["n"])


def W(x):
    return "n/a" if not x or x.get("pct") is None else "%.1f%% [%.1f, %.1f]" % (x["pct"], x["ci95"][0], x["ci95"][1])


def table(rows, head):
    out = ["| " + " | ".join(head) + " |", "|" + "|".join("---" for _ in head) + "|"]
    out += ["| " + " | ".join(map(str, r)) + " |" for r in rows]
    return "\n".join(out)


def main():
    h = json.loads((OUT / "headlines.json").read_text())
    a = json.loads((OUT / "audit_summary.json").read_text())
    R = h["random"]
    m = h["meta"]
    L = R["liveness"]
    O = R["onchain"]
    E = R["exact_url"]
    c = h["claims_funnel"]
    md = []
    md.append("# analysis - analysis (headlines, by-year, claims funnel, site data)\n")
    md.append("Generated by `scripts/analysis/run_all.py` (one command, re-runnable) at %s from the census snapshot finished up to %s. "
              "Census rows: %s. **Every number below is rendered from `data/analysis/headlines.json`.**\n" % (m["generated_at"], m["census_last_finished_at"], m["census_rows_by_stratum"]))
    md.append("## Method\n- Headlines use only the `random` stratum: a uniform random sample of %d of the %d non-spam collections with >=100 holders (seed %d; "
              "sample complete: %s). 95%% Wilson intervals are in brackets; `(k/n)` are raw counts. 'Top' stratum numbers are labelled descriptive and never mixed in.\n"
              "- Unit = collection. Weighted views (holders, tokens) are ratio estimates with a bootstrap CI.\n"
              "- Liveness is census's content-level verdict ('is some copy retrievable today'); the exact-URL view is separate (section 4).\n"
              "- 'Truly on-chain' = metadata AND all sampled media on-chain AND no external loading reference (census `onchain_candidate_clean`). It is a census-level static result; "
              "only collections that are also in the gallery gallery were render-tested unplugged.\n"
              "- For collections whose off-chain metadata could not be fetched the media location is **unresolved** (not 'none'); shown explicitly.\n" % (m["random_stratum_n"], m["population_non_spam_collections"], SEED, m["random_stratum_complete"]))
    md.append("## 1. Where the data lives (random stratum, n=%d)\n" % R["n"])
    md.append("**Metadata (tokenURI) location**\n\n" + table([(k, P(v)) for k, v in R["metadata_location"].items()], ["class", "share [95% CI]"]) + "\n")
    md.append("**Media location**, all collections (unresolved = off-chain metadata unreachable) and among those resolved (n=%d)\n\n" % R["media_location_resolved"]["n_resolved"] +
              table([(k, P(R["media_location_all"][k]), P(R["media_location_resolved"][k]) if k in R["media_location_resolved"] else "-") for k in R["media_location_all"]],
                    ["class", "of all", "of resolved"]) + "\n")
    md.append("**On-chain**\n\n" + table([
        ("metadata on-chain (data-uri + renderer)", P(O["metadata_onchain"])),
        ("media on-chain", P(O["media_onchain_all"])),
        ("**truly on-chain (census)**", P(O["truly_onchain_census"])),
        ("fake on-chain A: on-chain metadata, off-chain media (of all)", P(O["fake_onchain_A_offchain_media_of_all"])),
        ("fake on-chain A, of collections with on-chain metadata", P(O["fake_onchain_A_offchain_media_of_onchain_metadata"])),
        ("fake on-chain B: on-chain media that loads external refs (of all)", P(O["fake_onchain_B_onchain_media_external_refs_of_all"])),
        ("fake on-chain B, of on-chain metadata", P(O["fake_onchain_B_of_onchain_metadata"])),
        ("tokens disagree on class within a collection", P(O["metadata_mixed_across_tokens"]))], ["quantity", "share [95% CI]"]) + "\n")
    md.append("Media of the %d on-chain-metadata collections: %s. Metadata split: %s.\n" % (O["of_onchain_metadata_n"], O["onchain_metadata_media_split"], O["metadata_renderer_vs_datauri"]))
    md.append("## 2. Does it load today? (liveness)\n")
    md.append(table([(k, P(v)) for k, v in L["all"].items()], ["verdict", "share of all [95% CI]"]) + "\n")
    ue = L["unknown_excluded"]
    md.append("- Unknown excluded (n=%d): alive %s; degraded %s; dead %s; dead+degraded %s.\n"
              "- Bounds on **dead**: %s (unknown counted alive) to %s (unknown counted dead). Bounds on **dead or degraded**: %s to %s.\n"
              "- Restricted to collections with off-chain metadata (n=%d), dead+degraded with unknown excluded: %s.\n" % (
                  ue["n_resolved"], P(ue["alive"]), P(ue["degraded"]), P(ue["dead"]), P(ue["dead_or_degraded"]),
                  P(L["bounds_dead"]["lower_unknown_alive"]), P(L["bounds_dead"]["upper_unknown_dead"]),
                  P(L["bounds_dead_or_degraded"]["lower"]), P(L["bounds_dead_or_degraded"]["upper"]),
                  R["liveness_offchain_metadata_only"]["n"], P(R["liveness_offchain_metadata_only"]["dead_or_degraded_unknown_excluded"])))
    dr = R["dead_reasons"]
    md.append("**Dead or degraded by dominant reason** (share of all collections; %d collections)\n\n" % dr["n_dead_or_degraded"] +
              table([(k, P(v), P(dr["dead_or_degraded_share_of_failures"][k])) for k, v in dr["dead_or_degraded"].items()], ["reason", "of all", "of failures"]) +
              "\n\n`ipfs-not-found` = no public gateway serves the CID (mostly 504/404); `tokenURI-revert` = the contract call reverts for every sampled id (a different failure than a dead server); dead excluding reverts: %s. Dead with only soft IPFS/Arweave not-found evidence (gateway 504/404 within 15-40 s, not proof of deletion): %s; dead with hard evidence (DNS, TLS, 4xx/5xx, connection, revert, bad URI): %s. "
              "Why the `unknown` ones are unknown: %s.\n" % (P(dr["dead_excluding_tokenuri_revert"]), P(dr["dead_only_soft_ipfs_arweave_not_found"]), P(dr["dead_hard_evidence_dns_tls_http_revert_etc"]), dr["unknown_why"]))
    md.append("## 3. Weighting (random sample of collections is not a random NFT)\n")
    rows = []
    for k, v in R["weighted"].items():
        rows.append((k, v["n"]) + tuple(W(v[c_]) for c_ in ["meta_onchain", "truly_onchain", "fake_a", "dead_or_degraded", "unknown"]))
    md.append(table([("collection-weighted (headline)", R["n"], W(O["metadata_onchain"]), W(O["truly_onchain_census"]), W(O["fake_onchain_A_offchain_media_of_all"]),
                      W(L["bounds_dead_or_degraded"]["lower"]), W(L["all"]["unknown"]))] + rows,
                     ["view", "n", "meta on-chain", "truly on-chain", "fake A", "dead+degraded", "unknown"]) + "\n")
    for k, v in R["weighted"].items():
        md.append("- `%s`: %s" % (k, v["note"]))
    md.append("\nToken-weighted intervals are wide because a handful of very large collections dominate the weights.\n")
    md.append("## 4. Exact URL vs content (hard-coded gateways)\n")
    md.append("- Collections that hard-code any gateway host: %s.\n- Exact-URL liveness: %s.\n"
              "- **Content alive but the exact hard-coded URL is dead**: %s; by host: %s. Collections hard-coding a gateway that is dead per census's canary (any token): %s -> %s.\n"
              "- Content alive but exact URL **unmeasurable** (bot-walled gateway such as ipfs.io, dweb.link, nftstorage.link, pinata; HTTP 403/429 to non-browsers, ipfs.io sunset 2026-09-21): %s. These are not counted as dead.\n"
              % (P(E["collections_hardcoding_any_gateway"]), {k: P(v) for k, v in E["liveness_exact"].items()}, P(E["content_alive_exact_dead"]), E["content_alive_exact_dead_hosts"],
                 P(E["hardcode_a_dead_gateway_any_token"]), E["dead_gateway_hosts_collections"], P(E["content_alive_exact_unknown_botwalled"])))
    md.append(table([(r["host"], r["collections"], r["exact_alive"], r["exact_dead"], r["exact_unknown"], r["content_alive"], r["content_dead_or_degraded"]) for r in E["by_gateway_host"][:14]],
                    ["gateway host", "collections", "exact alive", "exact dead", "exact unknown", "content alive", "content dead/degraded"]) + "\n")
    md.append("## 5. By deploy year (random stratum; deploy year is a mint-year proxy)\n")
    md.append(table([(y["year"], y["n"], P(y["meta_onchain"], 0), P(y["truly_onchain"], 0), P(y["dead_or_degraded"], 0), P(y["unknown"], 0), W(y["holder_weighted_dead_or_degraded"]), W(y["holder_weighted_truly_onchain"]))
                     for y in R["by_year"]], ["year", "n", "metadata on-chain", "truly on-chain", "dead+degraded (of all)", "unknown", "dead+degraded, holder-weighted", "truly on-chain, holder-weighted"]) + "\n")
    md.append("Years <=2020 are tiny (see the pooled row); read single-year intervals before quoting.\n")
    md.append("Dead reasons by year: " + "; ".join("%s: %s" % (y["year"], y["dead_reasons"]) for y in R["by_year"] if y["year"] in ("2021", "2022", "2023", "2026")) + "\n")
    md.append("## 6. Claims vs reality (claims claimants x census x mutability x gallery; any stratum)\n")
    md.append("claims `claimants_reviewed.csv` has %d distinct manually reviewed project-authored claimants. Accepted claimants: %d (%d in the universe, %d spam-flagged); "
              "**%d are in the census so far** (%d not yet). Implied-only (directory headings) are excluded.\n" % (
                  c["w5_distinct_addresses_case_insensitive"], c["w5_non_implied_claimants"], c["w5_non_implied_in_universe"], c["w5_non_implied_spam_flagged"], c["claimants_in_census"], c["claimants_not_yet_in_census"]))
    fr = []
    for lab, key in (("all non-implied claimants", "all_claimants_non_implied"), ("explicit 100%/fully", "explicit_100"), ("generic on-chain", "generic"), ("random-stratum claimants only (unbiased, tiny)", "random_stratum_claimants_unbiased_subset")):
        z = c[key]
        fr.append((lab, z["claimants"], P(z["a_tokenURI_onchain"], 0), P(z["b_media_also_onchain"], 0), P(z["c_renders_unplugged_clean"], 0), z["c_of_which_render_tested_w4"], P(z["d_also_immutable"], 0), z["c_w6_not_assessed_or_unknown"]))
    md.append("Ordinary-pointer funnel: (a) tokenURI on-chain -> (b) media also on-chain -> (c) clean candidates (gallery rendering checked only where available) -> (d) also immutable (mutability `immutable`). These exclusions are not false storage-claim outcomes.\n\n" +
              table(fr, ["group", "n", "(a) tokenURI on-chain", "(b) + media on-chain", "(c) clean candidates", "of (c) render-tested", "(d) + immutable", "(c) without mutability verdict"]) + "\n")
    z = c["all_claimants_non_implied"]
    md.append("Where the all-claimants funnel breaks: %s. tokenURI location of claimants: %s. mutability class of claimants: %s. Baseline: truly on-chain among random non-claimants %s.\n" % (
        z["failed_at"], z["tokenURI_location"], c["w6_class_final_of_claimants"], P(c["baseline_random_nonclaimants_truly_onchain"])))
    md.append("Claimant sample strata: %s (the high-holder `top` stratum is over-represented in claimants because claimants are famous; the funnel is a property of the claimant set, not an estimate for the universe).\n" % c["by_stratum"])
    md.append("## 7. Sanity checks / misclassification\n")
    md.append("- Independent re-classification of the raw tokenURI string of all %d random-stratum token samples (own regex rules): %d disagreements (%.2f%%). Reviewed by hand: all are ambiguous malformed-CID strings "
              "(`ipfs://0`, truncated CIDs, a CID with the token id glued on, relative `ipfs/Qm...`) that census puts in `broken`/`http` and that I would call malformed ipfs. "
              "No case where census called an off-chain URI on-chain or vice versa. First-pass bug in my own regex (missed `bafk...` CIDs) was found and fixed by this check. Pairs: %s.\n"
              "- Liveness vs census's own evidence.jsonl: %d inconsistencies (no `alive` verdict without a 2xx fetch; no `dead` verdict where any fetch was alive).\n"
              "- Live DNS re-check (1.1.1.1) of %d hosts of collections census called dead by DNS: %d confirmed still failing (NXDOMAIN %d, SERVFAIL %d), the rest inconclusive (dig timeout).\n"
              "- Manual sample: `data/analysis/audit_sample.csv` (10 random rows per class: meta ipfs/http/arweave/on-chain/broken, live alive/dead/degraded/unknown, truly-on-chain, fake-on-chain-A) with the raw tokenURI re-decoded from the saved eth_call body (match rate %.0f%%). "
              "Hand review result is in section 8.\n" % (a["random_tokens_checked"], a["metadata_class_disagreements_tokens"], 100 * a["metadata_class_disagreement_rate"], a["disagreements_by_pair"],
                                                         a["liveness_evidence_inconsistencies"], a["dns_recheck"]["hosts_rechecked"], a["dns_recheck"]["still_failing_dns"], a["dns_recheck"]["NXDOMAIN"], a["dns_recheck"]["SERVFAIL"], 100 * (a["redecode_match_rate"] or 0)))
    man = ROOT / "scripts" / "analysis" / "manual_review.md"
    md.append("## 8. Manual review and open issues\n")
    md.append(man.read_text() if man.exists() else "(manual_review.md missing)")
    md.append("\n## 9. Files\n`data/analysis/headlines.json`, `collections_enriched.parquet` (analysis frame), `dead_hosts.csv`, `host_events.parquet`, `audit_*.{json,csv}`; "
              "`site/data/{census,collections,collections_extra}.json`, `site/data/evidence/<address>.json`. Run: `.venv/bin/python -I scripts/analysis/run_all.py`.\n")
    (NOTES / "analysis-analysis.md").write_text("\n".join(md))
    print("docs/methods/analysis.md written")


if __name__ == "__main__":
    main()
